'use strict';

/**
* Replace single-precision complex floating-point strided array elements equal to a provided search element with a specified scalar constant.
*
* @module @stdlib/blas-ext-base-cfill-equal
*
* @example
* var Complex64Array = require( '@stdlib/array-complex64' );
* var Complex64 = require( '@stdlib/complex-float32-ctor' );
* var cfillEqual = require( '@stdlib/blas-ext-base-cfill-equal' );
*
* var x = new Complex64Array( [ 1.0, 2.0, 0.0, 0.0, 3.0, 4.0, 0.0, 0.0 ] );
* var searchElement = new Complex64( 0.0, 0.0 );
* var alpha = new Complex64( 5.0, 5.0 );
*
* cfillEqual( x.length, searchElement, alpha, x, 1 );
* // x => <Complex64Array>[ 1.0, 2.0, 5.0, 5.0, 3.0, 4.0, 5.0, 5.0 ]
*
* @example
* var Complex64Array = require( '@stdlib/array-complex64' );
* var Complex64 = require( '@stdlib/complex-float32-ctor' );
* var cfillEqual = require( '@stdlib/blas-ext-base-cfill-equal' );
*
* var x = new Complex64Array( [ 1.0, 2.0, 0.0, 0.0, 3.0, 4.0, 0.0, 0.0 ] );
* var searchElement = new Complex64( 0.0, 0.0 );
* var alpha = new Complex64( 5.0, 5.0 );
*
* cfillEqual.ndarray( x.length, searchElement, alpha, x, 1, 0 );
* // x => <Complex64Array>[ 1.0, 2.0, 5.0, 5.0, 3.0, 4.0, 5.0, 5.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils-try-require' );
var isError = require( '@stdlib/assert-is-error' );
var main = require( './main.js' );


// MAIN //

var cfillEqual;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	cfillEqual = main;
} else {
	cfillEqual = tmp;
}


// EXPORTS //

module.exports = cfillEqual;

// exports: { "ndarray": "cfillEqual.ndarray" }
